const Portfolio = ({ onGridItemClick }) => {
    const flipContainerRef = useRef(null);

    const headerRef = useRef(null);
    const socialLinksRef = useRef(null);
    const nameContainerRef = useRef(null);
    const sentinelRef = useRef(null);
